input.new_string:
if balance_cents < 0 or days_late < 0:
    raise ValueError("balance_cents and days_late must be non-negative")
if balance_cents == 0 or days_late <= GRACE_DAYS:
    return 0
# Days 1-30 are period 1, days 31-60 are period 2, etc. (ceiling division)
periods = (days_late - 1) // PERIOD_DAYS + 1
# Round half-up: add 5000 before integer dividing by 10000
fee = (balance_cents * RATE_BP * periods + 5000) // 10000
cap = balance_cents // 5
# Cap wins if fee exceeds it; otherwise apply minimum floor
if fee > cap:
    return cap
return max(fee, MINIMUM_FEE_CENTS)
